// Claude's review tests for A11 (match on query, body or a header). agy: do not edit this file.
import { expect, test, type Page } from '@playwright/test';
import { emptyState, type Mock, type Project, type WemockState } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

function mock(id: string, method: Mock['method'], urlPattern: string, extra: Partial<Mock> = {}): Mock {
  return {
    id,
    name: id,
    enabled: true,
    method,
    urlPattern,
    response: { status: 200, headers: { 'content-type': 'text/plain' }, body: id, bodyEncoding: 'text', delayMs: 0 },
    source: 'manual',
    createdAt: 0,
    ...extra,
  };
}

function project(): Project {
  return {
    id: 'p1',
    name: 'site',
    origins: [fixture.origin],
    activeScenarioId: 'default',
    scenarios: [{
      id: 'default',
      name: 'Default',
      mocks: [
        mock('all', 'GET', '/api/items'),
        mock('page2', 'GET', '/api/items', { match: { query: { page: '2' } } }),
        mock('debug', 'GET', '/api/items', { match: { query: { debug: '*' } } }),
        mock('admin', 'GET', '/api/items', { match: { headers: { 'X-Role': 'admin' } } }),
        mock('other', 'POST', '/api/login'),
        mock('anna', 'POST', '/api/login', { match: { body: '{"user":"anna"}' } }),
        mock('who', 'GET', '/api/who', { reply: 'code', code: "return { who: req.headers['x-user'] || 'none' };" }),
      ],
    }],
  };
}

async function readState(): Promise<WemockState> {
  return session.worker.evaluate(async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (await (globalThis as any).chrome.storage.local.get('wemock.state'))['wemock.state'];
  });
}

async function open(): Promise<{ page: Page; panel: Page }> {
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [project()] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
  return { page, panel };
}

test('the page gets the mock whose conditions hold, through fetch and XHR', async () => {
  const { page, panel } = await open();
  try {
    const got = await page.evaluate(async () => {
      const get = async (url: string, init?: RequestInit) => (await fetch(url, init)).text();
      const xhr = (url: string, headers: Record<string, string>, body?: string) =>
        new Promise<string>((resolve) => {
          const x = new XMLHttpRequest();
          x.open(body === undefined ? 'GET' : 'POST', url);
          for (const [k, v] of Object.entries(headers)) x.setRequestHeader(k, v);
          x.onload = () => resolve(x.responseText);
          x.send(body);
        });
      return {
        plain: await get('/api/items'),
        page2: await get('/api/items?page=2'),
        page3: await get('/api/items?page=3'),
        debug: await get('/api/items?debug='),
        admin: await get('/api/items', { headers: { 'X-Role': 'admin' } }),
        adminRequest: await get(new Request('/api/items', { headers: { 'x-role': 'admin' } }) as unknown as string),
        adminXhr: await xhr('/api/items', { 'x-role': 'admin' }),
        anna: await get('/api/login', { method: 'POST', headers: { 'content-type': 'application/json' }, body: '{"user":"anna","pw":"x"}' }),
        bob: await get('/api/login', { method: 'POST', body: '{"user":"bob"}' }),
        annaXhr: await xhr('/api/login', {}, '{"pw":"y","user":"anna"}'),
      };
    });
    expect(got).toEqual({
      plain: 'all', page2: 'page2', page3: 'all', debug: 'debug', admin: 'admin', adminRequest: 'admin',
      adminXhr: 'admin', anna: 'anna', bob: 'other', annaXhr: 'anna',
    });
  } finally {
    await panel.close();
    await page.close();
  }
});

test('the editor shows the conditions of a mock that has them, and saves edits', async () => {
  const { page, panel } = await open();
  try {
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('mock-row').filter({ hasText: 'page2' }).click();
    await expect(panel.getByTestId('match-section')).toBeVisible();
    await expect(panel.getByTestId('match-query-key')).toHaveValue('page');
    await expect(panel.getByTestId('match-query-value')).toHaveValue('2');

    await panel.getByTestId('match-query-value').fill('5');
    await panel.getByTestId('match-header-add').click();
    await panel.getByTestId('match-header-key').fill('x-team');
    await panel.getByTestId('match-header-value').fill('red');
    await panel.getByTestId('match-body').fill('{"a":1}');
    await panel.getByTestId('mock-save').click();
    await expect.poll(async () => (await readState()).projects[0]!.scenarios[0]!.mocks[1]!.match).toEqual({
      query: { page: '5' },
      headers: { 'x-team': 'red' },
      body: '{"a":1}',
    });
  } finally {
    await panel.close();
    await page.close();
  }
});

test('a mock with no conditions has the section folded; added then emptied rows store no match', async () => {
  const { page, panel } = await open();
  try {
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('mock-row').filter({ hasText: 'all' }).click();
    await expect(panel.getByTestId('match-section')).toHaveCount(0);
    await panel.getByTestId('match-toggle').click();
    await expect(panel.getByTestId('match-section')).toBeVisible();
    await panel.getByTestId('match-query-add').click();
    await panel.getByTestId('match-query-key').fill('');
    await panel.getByTestId('mock-save').click();
    await panel.waitForTimeout(500);
    const saved = (await readState()).projects[0]!.scenarios[0]!.mocks[0]!;
    expect(saved.match).toBeUndefined();
  } finally {
    await panel.close();
    await page.close();
  }
});

test('the Test bar takes request headers', async () => {
  const { page, panel } = await open();
  try {
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('test-method').selectOption('GET');
    await panel.getByTestId('test-url').fill('/api/items');
    await panel.getByTestId('test-req-headers').fill('X-Role: admin\nx-other: 1');
    await panel.getByTestId('test-run').click();
    await expect(panel.getByTestId('test-match')).toContainText('admin');
    await panel.getByTestId('test-req-headers').fill('');
    await panel.getByTestId('test-run').click();
    await expect(panel.getByTestId('test-match')).toContainText('all');
  } finally {
    await panel.close();
    await page.close();
  }
});

test('the Test bar passes its headers to a code mock', async () => {
  const { page, panel } = await open();
  try {
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('test-method').selectOption('GET');
    await panel.getByTestId('test-url').fill('/api/who');
    await panel.getByTestId('test-req-headers').fill('x-user: anna');
    await panel.getByTestId('test-run').click();
    await expect(panel.getByTestId('test-body-out')).toContainText('anna');
  } finally {
    await panel.close();
    await page.close();
  }
});
